mapper.select:

SELECT  COUNT(a.common_code) AS cnt 		  
FROM  lgcom_common_code_c a
WHERE a.code_type_code = #{codeTypeCode}
AND   a.common_code = #{commonCode}  		
AND   a.company_id = #{companyId}
AND   a.inventory_organization_id = #{inventoryOrganizationId}


SELECT  COUNT(a.code_type_code) AS cnt 		  
FROM  lgcom_common_code_multi_lang_c a
WHERE a.code_type_code = #{codeTypeCode}
AND   a.common_code = #{commonCode}  
AND   a.company_id = #{companyId}
AND   a.inventory_organization_id = #{inventoryOrganizationId}
AND   a.language_code = #{languageCode}

mapper.insert:
INSERT INTO LGCOM_COMMON_CODE_C
( COMMON_CODE
, CODE_TYPE_CODE
, COMPANY_ID
, INVENTORY_ORGANIZATION_ID
, COMMON_CODE_DESC
, PARENT_COMMON_CODE
, PARENT_CODE_TYPE_CODE
, USE_FLAG
, APPLY_START_DATE
, APPLY_END_DATE
, SORT_ORDER_NO
, CODE_DATA1_VALUE
, CODE_DATA2_VALUE
, CODE_DATA3_VALUE
, CODE_DATA4_VALUE
, CODE_DATA5_VALUE
, CREATED_BY
, CREATION_DATE
, LAST_UPDATED_BY
, LAST_UPDATE_DATE
) values
(  #{commonCode}
 , #{codeTypeCode}
 , #{companyId}
 , #{inventoryOrganizationId}
 , #{commonCodeDesc}		 
 , #{parentCommonCode}
 , #{parentCodeTypeCode}
 , #{useFlag}
 , TO_DATE(#{applyStartDate},'YYYY-MM-DD')         
 , TO_DATE(#{applyEndDate},'YYYY-MM-DD')
 , #{sortOrderNo}
 , #{codeData1Value}
 , #{codeData2Value}
 , #{codeData3Value}
 , #{codeData4Value}
 , #{codeData5Value}
 , #{sessionUserId}
 , SYSDATE
 , #{sessionUserId}
 , SYSDATE
)

mapper.update:
UPDATE LGCOM_COMMON_CODE_C
   SET COMMON_CODE_DESC      = #{commonCodeDesc}            
	 , PARENT_COMMON_CODE    = #{parentCommonCode}          
	 , PARENT_CODE_TYPE_CODE = #{parentCodeTypeCode}
	 , USE_FLAG              = #{useFlag}        
	 , APPLY_START_DATE      = TO_DATE(#{applyStartDate},'YYYY-MM-DD')         
	 , APPLY_END_DATE        = TO_DATE(#{applyEndDate},'YYYY-MM-DD')     
	 , SORT_ORDER_NO         = #{sortOrderNo}               
	 , CODE_DATA1_VALUE      = #{codeData1Value}               
	 , CODE_DATA2_VALUE      = #{codeData2Value}                 
	 , CODE_DATA3_VALUE      = #{codeData3Value}                  
	 , CODE_DATA4_VALUE      = #{codeData4Value}            
	 , CODE_DATA5_VALUE      = #{codeData5Value}            
     , LAST_UPDATED_BY    	 = #{sessionUserId}
     , LAST_UPDATE_DATE    	 = SYSDATE
 WHERE COMMON_CODE     			= #{commonCode}
   AND CODE_TYPE_CODE         	= #{codeTypeCode}
   AND COMPANY_ID         		= #{companyId}
   AND INVENTORY_ORGANIZATION_ID= #{inventoryOrganizationId}

mapper.insert:
	INSERT INTO LGCOM_COMMON_CODE_MULTI_LANG_C
	( CODE_TYPE_CODE
	, COMMON_CODE
	, COMPANY_ID
	, INVENTORY_ORGANIZATION_ID
	, LANGUAGE_CODE
	, COMMON_CODE_NAME
	, CREATED_BY
	, CREATION_DATE
	, LAST_UPDATED_BY
	, LAST_UPDATE_DATE
	) VALUES
	( #{codeTypeCode}
	, #{commonCode}
    , #{companyId}
	, #{inventoryOrganizationId}
	, #{languageCode}
	, #{commonCodeName}
	, #{sessionUserId}
	, SYSDATE
	, #{sessionUserId}
	, SYSDATE
	)

mapper.update:
UPDATE LGCOM_COMMON_CODE_MULTI_LANG_C
   SET COMMON_CODE_NAME      	= #{commonCodeName}
     , LAST_UPDATED_BY   		= #{sessionUserId}
     , LAST_UPDATE_DATE 		= SYSDATE
 WHERE CODE_TYPE_CODE 			= #{codeTypeCode}
   AND COMMON_CODE 				= #{commonCode}
   AND COMPANY_ID 				= #{companyId}
   AND LANGUAGE_CODE 			= #{languageCode}
   AND INVENTORY_ORGANIZATION_ID= #{inventoryOrganizationId}

DELETE FROM LGCOM_COMMON_CODE_MULTI_LANG_C
 WHERE CODE_TYPE_CODE 			= #{codeTypeCode}
   AND COMMON_CODE 				= #{commonCode}
   AND COMPANY_ID 				= #{companyId}
   AND LANGUAGE_CODE 			= #{languageCode}
   AND INVENTORY_ORGANIZATION_ID= #{inventoryOrganizationId}
